css:
    .print-format {
        font-family: Arial, sans-serif;
        font-size: 12px;
    }

    .print-format h2 {
        text-align: center;
        margin-bottom: 20px;
    }

    .agreement-table {
        width: 100%;
        border-collapse: collapse;
        margin-top: 20px;
    }

    .agreement-table th,
    .agreement-table td {
        border: 1px solid #000;
        padding: 8px;
        text-align: left;
    }

    .agreement-table th {
        font-weight: bold;
        background-color: #f2f2f2;
    }

    .agreement-table td:nth-child(3),
    .agreement-table td:nth-child(4),
    .agreement-table td:nth-child(5) {
        text-align: right;
    }

    .totals {
        margin-top: 20px;
        text-align: right;
        line-height: 1.8;
    }

    .generated-date {
        margin-top: 30px;
        font-size: 9px;
        color: #666;
    }
